<?php require_once 'config/database.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$type=$_POST['membership_type']??'Starter';$pass=$_POST['password']??'';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=8){$s=$pdo->prepare('INSERT INTO Members(full_name,email,phone,membership_type,password_hash) VALUES(?,?,?,?,?)');try{$s->execute([$name,$email,$phone,$type,password_hash($pass,PASSWORD_DEFAULT)]);$message='Registration successful. You can now log in.';}catch(PDOException $e){$message='That email address may already be registered.';}}else{$message='Please complete the form and use a password of at least 8 characters.';}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | FightClubSA</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header><div class="wrap nav"><a class="logo" href="Index.php">FIGHT<span>CLUBSA</span></a><nav><ul><li><a href="Index.php">Home</a></li><li><a href="catalog.php">Classes</a></li><li><a href="login.php">Login</a></li></ul></nav></div></header><main><div class="form-box"><div class="time">JOIN FIGHTCLUBSA</div><h2>Create Account</h2><?php if($message):?><div class="notice"><?=htmlspecialchars($message)?></div><?php endif;?><form method="post"><label>Full Name<input name="full_name" required></label><label>Email Address<input type="email" name="email" required></label><label>Phone Number<input name="phone"></label><label>Membership Type<select name="membership_type"><option>Starter</option><option>Fighter</option><option>Elite</option></select></label><label>Password<input type="password" name="password" required></label><button class="btn full">CREATE ACCOUNT</button></form></div></main><footer>FightClubSA</footer></body></html>
